-- TEC-20 Pass, set and play – combinazione con manichino (insert o aggiornamento)
insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-00000000013e', '{"code":"TEC-20","title":"Pass, set and play – combinazione con manichino","area":"tecnica","fase":["attivazione"],"obiettivi":["passaggio","ricezione","uno-due","controllo orientato","postura del corpo"],"eta":"U9-U13","giocatori":"6-8 (2 stazioni)","spazio":"20x12 m","durata":10,"materiale":"4 paletti (2 porte), 2 manichini, 4 cinesini, palloni","perche":"Attivazione con palla: qualità del passaggio, appoggio di ritorno (set), movimento per ricevere in corsa e passaggio diagonale. Alza ritmo e intensità prima della parte centrale.","descrizione":"Setup: area 20x12 m con 2 stazioni. In ogni stazione una porta di paletti al centro, un manichino accanto alla porta e i giocatori sui cinesini esterni ai due lati.\nEsecuzione: il primo giocatore passa attraverso la porta al compagno di fronte; il compagno appoggia di ritorno (set) attraverso la stessa porta. Chi ha passato gioca il pallone all’esterno del manichino e il compagno lo riceve in corsa. Da lì palla in diagonale alla stazione successiva, dove la stessa sequenza riparte nella direzione opposta.\nOgni giocatore segue il proprio passaggio verso la posizione successiva: esercizio continuo, ritmo alto.","rotazione":"Segui il passaggio: chi passa prende il posto di chi riceve; chi gioca la diagonale va nella fila della stazione successiva.","varianti":"Massimo 2 tocchi, poi 1 tocco. Solo piede debole. Più giocatori per stazione per aumentare i recuperi. Due palloni in contemporanea (uno per stazione).","coaching":"Passaggio forte e preciso tra i paletti. Set di prima, morbido, sul piede del compagno. Ricezione in corsa con postura aperta verso la stazione successiva. Diagonale tesa. Tenere il ritmo.","fonte":"Video drill “Pass, set and play” (inviato da Andrea, 23/10/2026)","diagram":{"field":{"preset":"spazio","w":20,"h":12},"steps":[{"title":"Passaggio nella porta","note":"9 passa a 5 tra i paletti"},{"title":"Set","note":"5 appoggia di ritorno nella stessa porta"},{"title":"Fuori dal manichino","note":"9 gioca all’esterno del manichino, 5 riceve in corsa"},{"title":"Diagonale","note":"5 gioca in diagonale a 11 e segue il passaggio"},{"title":"Stazione 2: porta","note":"11 passa a 7 tra i paletti"},{"title":"Set","note":"7 appoggia di ritorno"},{"title":"Fuori dal manichino","note":"11 gioca all’esterno del manichino, 7 riceve in corsa"},{"title":"Diagonale","note":"7 gioca in diagonale a 10: si riparte"},{"title":"Ricomincia"}],"items":[{"id":"it1101","type":"disc","pos":{"0":{"x":4.5,"y":0.6}}},{"id":"it1102","type":"disc","pos":{"0":{"x":4.5,"y":11.4}}},{"id":"it1103","type":"disc","pos":{"0":{"x":15.5,"y":0.6}}},{"id":"it1104","type":"disc","pos":{"0":{"x":15.5,"y":11.4}}},{"id":"it1105","type":"pole","pos":{"0":{"x":4,"y":6}}},{"id":"it1106","type":"pole","pos":{"0":{"x":7,"y":6}}},{"id":"it1107","type":"pole","pos":{"0":{"x":13,"y":6}}},{"id":"it1108","type":"pole","pos":{"0":{"x":16,"y":6}}},{"id":"it1109","type":"mannequin","pos":{"0":{"x":3.2,"y":5.4}}},{"id":"it1110","type":"mannequin","pos":{"0":{"x":16.8,"y":5.4}}},{"id":"it1111","type":"playerA","label":"9","pos":{"0":{"x":5.5,"y":1.8},"4":{"x":5.5,"y":10.2}}},{"id":"it1112","type":"playerA","label":"10","pos":{"0":{"x":3.3,"y":1},"4":{"x":5.5,"y":1.8}}},{"id":"it1113","type":"playerA","label":"5","pos":{"0":{"x":5.5,"y":10.2},"3":{"x":2.4,"y":9.4},"4":{"x":12.8,"y":1},"8":{"x":14.5,"y":1.8}}},{"id":"it1114","type":"playerA","label":"11","pos":{"0":{"x":14.5,"y":1.8},"8":{"x":16.4,"y":11}}},{"id":"it1115","type":"playerA","label":"7","pos":{"0":{"x":14.5,"y":10.2},"7":{"x":17.6,"y":9.4},"8":{"x":3.3,"y":1}}},{"id":"it1116","type":"playerA","label":"6","pos":{"0":{"x":16.4,"y":11},"8":{"x":14.5,"y":10.2}}},{"id":"it1117","type":"ball","pos":{"0":{"x":6.1,"y":2.2},"1":{"x":5.5,"y":9.6},"2":{"x":6.1,"y":2.2},"3":{"x":2.9,"y":9.8},"4":{"x":13.9,"y":2.2},"5":{"x":14.5,"y":9.6},"6":{"x":13.9,"y":2.2},"7":{"x":17.1,"y":9.8},"8":{"x":6.1,"y":2.2}}}],"arrows":[{"id":"ar1118","kind":"pass","step":0,"from":{"x":6.1,"y":2.2},"to":{"x":5.5,"y":9.6}},{"id":"ar1119","kind":"pass","step":1,"from":{"x":5.5,"y":9.6},"to":{"x":6.1,"y":2.2},"curve":0.8},{"id":"ar1120","kind":"pass","step":2,"from":{"x":6.1,"y":2.2},"to":{"x":2.9,"y":9.8},"curve":5},{"id":"ar1121","kind":"run","step":2,"from":{"x":5.5,"y":10.2},"to":{"x":2.4,"y":9.4}},{"id":"ar1122","kind":"pass","step":3,"from":{"x":2.9,"y":9.8},"to":{"x":13.9,"y":2.2}},{"id":"ar1123","kind":"run","step":3,"from":{"x":2.4,"y":9.4},"to":{"x":12.8,"y":1},"curve":1.5},{"id":"ar1124","kind":"run","step":3,"from":{"x":5.5,"y":1.8},"to":{"x":5.5,"y":10.2},"curve":3},{"id":"ar1125","kind":"run","step":3,"from":{"x":3.3,"y":1},"to":{"x":5.5,"y":1.8}},{"id":"ar1126","kind":"pass","step":4,"from":{"x":13.9,"y":2.2},"to":{"x":14.5,"y":9.6}},{"id":"ar1127","kind":"pass","step":5,"from":{"x":14.5,"y":9.6},"to":{"x":13.9,"y":2.2},"curve":-0.8},{"id":"ar1128","kind":"pass","step":6,"from":{"x":13.9,"y":2.2},"to":{"x":17.1,"y":9.8},"curve":-5},{"id":"ar1129","kind":"run","step":6,"from":{"x":14.5,"y":10.2},"to":{"x":17.6,"y":9.4}},{"id":"ar1130","kind":"pass","step":7,"from":{"x":17.1,"y":9.8},"to":{"x":6.1,"y":2.2}},{"id":"ar1131","kind":"run","step":7,"from":{"x":17.6,"y":9.4},"to":{"x":3.3,"y":1},"curve":-1.5},{"id":"ar1132","kind":"run","step":7,"from":{"x":14.5,"y":1.8},"to":{"x":16.4,"y":11},"curve":-3},{"id":"ar1133","kind":"run","step":7,"from":{"x":16.4,"y":11},"to":{"x":14.5,"y":10.2}},{"id":"ar1134","kind":"run","step":7,"from":{"x":12.8,"y":1},"to":{"x":14.5,"y":1.8}}]},"id":"5eed0000-0000-4000-8000-00000000013e","updatedAt":"2026-10-01T00:00:00.000Z"}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = now();
